import React, { useState, useEffect } from 'react';
import {
  UserIcon,
  KeyIcon,
  BuildingOfficeIcon,
  CheckIcon,
  ExclamationTriangleIcon,
  EyeIcon,
  EyeSlashIcon
} from '@heroicons/react/24/outline';
import apiService from '../services/api';
import { useNotification } from '../contexts/NotificationContext';

const UserSettings = () => {
  const [activeTab, setActiveTab] = useState('personal');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const { showNotification } = useNotification();

  // Personal Information State
  const [personalInfo, setPersonalInfo] = useState({
    first_name: '',
    last_name: '',
    email: '',
    username: ''
  });

  // Password Change State
  const [passwordData, setPasswordData] = useState({
    current_password: '',
    new_password: '',
    confirm_password: ''
  });
  const [showPasswords, setShowPasswords] = useState({
    current: false,
    new: false,
    confirm: false
  });

  // Company Information State
  const [companyInfo, setCompanyInfo] = useState({
    nombre: '',
    direccion: '',
    total_usuarios: 0,
    total_dominios: 0
  });

  // User permissions and role
  const [userPermissions, setUserPermissions] = useState({});
  const [userRole, setUserRole] = useState('');

  const tabs = [
    { id: 'personal', name: 'Información Personal', icon: UserIcon },
    { id: 'password', name: 'Cambiar Contraseña', icon: KeyIcon },
    { id: 'company', name: 'Información de Empresa', icon: BuildingOfficeIcon }
  ];

  useEffect(() => {
    loadUserProfile();
  }, []);

  const loadUserProfile = async () => {
    try {
      setLoading(true);
      const response = await apiService.get('/auth/profile/');

      setPersonalInfo({
        first_name: response.first_name || '',
        last_name: response.last_name || '',
        email: response.email || '',
        username: response.username || ''
      });

      setUserPermissions(response.permissions || {});
      setUserRole(response.computed_role || '');

      // Load company information if user has a company
      if (response.empresa) {
        await loadCompanyInfo(response.empresa);
      }
    } catch (error) {
      console.error('Error loading user profile:', error);
      showNotification('Error al cargar el perfil de usuario', 'error');
    } finally {
      setLoading(false);
    }
  };

  const loadCompanyInfo = async (companyId) => {
    try {
      const response = await apiService.get(`/auth/empresas/${companyId}/`);
      setCompanyInfo({
        nombre: response.nombre || '',
        direccion: response.direccion || '',
        total_usuarios: response.total_usuarios || 0,
        total_dominios: response.total_dominios || 0
      });
    } catch (error) {
      console.error('Error loading company info:', error);
      showNotification('Error al cargar información de la empresa', 'error');
    }
  };

  const handlePersonalInfoSubmit = async (e) => {
    e.preventDefault();
    try {
      setSaving(true);
      await apiService.put('/auth/profile/', personalInfo);
      showNotification('Información personal actualizada correctamente', 'success');
    } catch (error) {
      console.error('Error updating personal info:', error);
      showNotification('Error al actualizar la información personal', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handlePasswordSubmit = async (e) => {
    e.preventDefault();

    if (passwordData.new_password !== passwordData.confirm_password) {
      showNotification('Las contraseñas nuevas no coinciden', 'error');
      return;
    }

    if (passwordData.new_password.length < 8) {
      showNotification('La nueva contraseña debe tener al menos 8 caracteres', 'error');
      return;
    }

    try {
      setSaving(true);
      await apiService.post('/auth/change-password/', {
        old_password: passwordData.current_password,
        new_password: passwordData.new_password
      });

      setPasswordData({
        current_password: '',
        new_password: '',
        confirm_password: ''
      });

      showNotification('Contraseña cambiada correctamente', 'success');
    } catch (error) {
      console.error('Error changing password:', error);
      const errorMessage = error.response?.data?.detail || 'Error al cambiar la contraseña';
      showNotification(errorMessage, 'error');
    } finally {
      setSaving(false);
    }
  };

  const togglePasswordVisibility = (field) => {
    setShowPasswords(prev => ({
      ...prev,
      [field]: !prev[field]
    }));
  };

  const getRoleDisplayName = (role) => {
    const roleNames = {
      'super_admin': 'Super Administrador',
      'company_admin': 'Administrador de Empresa',
      'config_user': 'Usuario de Configuración',
      'read_only': 'Solo Lectura'
    };
    return roleNames[role] || role;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="spinner h-12 w-12 mx-auto mb-4"></div>
          <p className="text-gray-600">Cargando configuración...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="py-6">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          {/* Header */}
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900">Configuración</h1>
            <p className="mt-2 text-gray-600">
              Gestiona tu información personal, contraseña y configuración de empresa
            </p>
          </div>

          {/* Tabs */}
          <div className="border-b border-gray-200 mb-8">
            <nav className="-mb-px flex space-x-8">
              {tabs.map((tab) => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`${
                      activeTab === tab.id
                        ? 'border-primary-500 text-primary-600'
                        : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    } whitespace-nowrap py-2 px-1 border-b-2 font-medium text-sm flex items-center`}
                  >
                    <Icon className="h-5 w-5 mr-2" />
                    {tab.name}
                  </button>
                );
              })}
            </nav>
          </div>

          {/* Tab Content */}
          <div className="max-w-3xl">
            {/* Personal Information Tab */}
            {activeTab === 'personal' && (
              <div className="bg-white shadow rounded-lg">
                <div className="px-6 py-4 border-b border-gray-200">
                  <h3 className="text-lg font-medium text-gray-900">Información Personal</h3>
                  <p className="mt-1 text-sm text-gray-600">
                    Actualiza tu información personal y de contacto
                  </p>
                </div>
                <form onSubmit={handlePersonalInfoSubmit} className="px-6 py-4 space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label htmlFor="first_name" className="block text-sm font-medium text-gray-700 mb-2">
                        Nombre
                      </label>
                      <input
                        type="text"
                        id="first_name"
                        value={personalInfo.first_name}
                        onChange={(e) => setPersonalInfo(prev => ({ ...prev, first_name: e.target.value }))}
                        className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
                        placeholder="Tu nombre"
                      />
                    </div>
                    <div>
                      <label htmlFor="last_name" className="block text-sm font-medium text-gray-700 mb-2">
                        Apellido
                      </label>
                      <input
                        type="text"
                        id="last_name"
                        value={personalInfo.last_name}
                        onChange={(e) => setPersonalInfo(prev => ({ ...prev, last_name: e.target.value }))}
                        className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
                        placeholder="Tu apellido"
                      />
                    </div>
                  </div>

                  <div>
                    <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                      Correo Electrónico
                    </label>
                    <input
                      type="email"
                      id="email"
                      value={personalInfo.email}
                      readOnly
                      className="block w-full rounded-md border-gray-300 bg-gray-50 shadow-sm sm:text-sm"
                    />
                    <p className="mt-1 text-xs text-gray-500">
                      El correo electrónico no se puede modificar
                    </p>
                  </div>

                  <div>
                    <label htmlFor="username" className="block text-sm font-medium text-gray-700 mb-2">
                      Nombre de Usuario
                    </label>
                    <input
                      type="text"
                      id="username"
                      value={personalInfo.username}
                      readOnly
                      className="block w-full rounded-md border-gray-300 bg-gray-50 shadow-sm sm:text-sm"
                    />
                    <p className="mt-1 text-xs text-gray-500">
                      El nombre de usuario no se puede modificar
                    </p>
                  </div>

                  {/* User Role Display */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Rol en el Sistema
                    </label>
                    <div className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-blue-100 text-blue-800">
                      {getRoleDisplayName(userRole)}
                    </div>
                  </div>

                  <div className="flex justify-end">
                    <button
                      type="submit"
                      disabled={saving}
                      className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {saving ? (
                        <>
                          <div className="spinner h-4 w-4 mr-2"></div>
                          Guardando...
                        </>
                      ) : (
                        <>
                          <CheckIcon className="h-4 w-4 mr-2" />
                          Guardar Cambios
                        </>
                      )}
                    </button>
                  </div>
                </form>
              </div>
            )}

            {/* Password Change Tab */}
            {activeTab === 'password' && (
              <div className="bg-white shadow rounded-lg">
                <div className="px-6 py-4 border-b border-gray-200">
                  <h3 className="text-lg font-medium text-gray-900">Cambiar Contraseña</h3>
                  <p className="mt-1 text-sm text-gray-600">
                    Actualiza tu contraseña para mantener tu cuenta segura
                  </p>
                </div>
                <form onSubmit={handlePasswordSubmit} className="px-6 py-4 space-y-6">
                  <div>
                    <label htmlFor="current_password" className="block text-sm font-medium text-gray-700 mb-2">
                      Contraseña Actual
                    </label>
                    <div className="relative">
                      <input
                        type={showPasswords.current ? 'text' : 'password'}
                        id="current_password"
                        value={passwordData.current_password}
                        onChange={(e) => setPasswordData(prev => ({ ...prev, current_password: e.target.value }))}
                        className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm pr-10"
                        placeholder="Ingresa tu contraseña actual"
                        required
                      />
                      <button
                        type="button"
                        onClick={() => togglePasswordVisibility('current')}
                        className="absolute inset-y-0 right-0 pr-3 flex items-center"
                      >
                        {showPasswords.current ? (
                          <EyeSlashIcon className="h-5 w-5 text-gray-400" />
                        ) : (
                          <EyeIcon className="h-5 w-5 text-gray-400" />
                        )}
                      </button>
                    </div>
                  </div>

                  <div>
                    <label htmlFor="new_password" className="block text-sm font-medium text-gray-700 mb-2">
                      Nueva Contraseña
                    </label>
                    <div className="relative">
                      <input
                        type={showPasswords.new ? 'text' : 'password'}
                        id="new_password"
                        value={passwordData.new_password}
                        onChange={(e) => setPasswordData(prev => ({ ...prev, new_password: e.target.value }))}
                        className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm pr-10"
                        placeholder="Ingresa tu nueva contraseña"
                        required
                        minLength={8}
                      />
                      <button
                        type="button"
                        onClick={() => togglePasswordVisibility('new')}
                        className="absolute inset-y-0 right-0 pr-3 flex items-center"
                      >
                        {showPasswords.new ? (
                          <EyeSlashIcon className="h-5 w-5 text-gray-400" />
                        ) : (
                          <EyeIcon className="h-5 w-5 text-gray-400" />
                        )}
                      </button>
                    </div>
                    <p className="mt-1 text-xs text-gray-500">
                      La contraseña debe tener al menos 8 caracteres
                    </p>
                  </div>

                  <div>
                    <label htmlFor="confirm_password" className="block text-sm font-medium text-gray-700 mb-2">
                      Confirmar Nueva Contraseña
                    </label>
                    <div className="relative">
                      <input
                        type={showPasswords.confirm ? 'text' : 'password'}
                        id="confirm_password"
                        value={passwordData.confirm_password}
                        onChange={(e) => setPasswordData(prev => ({ ...prev, confirm_password: e.target.value }))}
                        className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm pr-10"
                        placeholder="Confirma tu nueva contraseña"
                        required
                      />
                      <button
                        type="button"
                        onClick={() => togglePasswordVisibility('confirm')}
                        className="absolute inset-y-0 right-0 pr-3 flex items-center"
                      >
                        {showPasswords.confirm ? (
                          <EyeSlashIcon className="h-5 w-5 text-gray-400" />
                        ) : (
                          <EyeIcon className="h-5 w-5 text-gray-400" />
                        )}
                      </button>
                    </div>
                  </div>

                  {passwordData.new_password && passwordData.confirm_password && 
                   passwordData.new_password !== passwordData.confirm_password && (
                    <div className="flex items-center text-red-600 text-sm">
                      <ExclamationTriangleIcon className="h-4 w-4 mr-1" />
                      Las contraseñas no coinciden
                    </div>
                  )}

                  <div className="flex justify-end">
                    <button
                      type="submit"
                      disabled={saving || !passwordData.current_password || !passwordData.new_password || 
                               passwordData.new_password !== passwordData.confirm_password}
                      className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {saving ? (
                        <>
                          <div className="spinner h-4 w-4 mr-2"></div>
                          Cambiando...
                        </>
                      ) : (
                        <>
                          <KeyIcon className="h-4 w-4 mr-2" />
                          Cambiar Contraseña
                        </>
                      )}
                    </button>
                  </div>
                </form>
              </div>
            )}

            {/* Company Information Tab */}
            {activeTab === 'company' && (
              <div className="bg-white shadow rounded-lg">
                <div className="px-6 py-4 border-b border-gray-200">
                  <h3 className="text-lg font-medium text-gray-900">Información de Empresa</h3>
                  <p className="mt-1 text-sm text-gray-600">
                    Información de la empresa asociada a tu cuenta
                  </p>
                </div>
                <div className="px-6 py-4 space-y-6">
                  {companyInfo.nombre ? (
                    <>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Nombre de la Empresa
                        </label>
                        <div className="text-lg font-semibold text-gray-900">
                          {companyInfo.nombre}
                        </div>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Dirección
                        </label>
                        <div className="text-gray-900">
                          {companyInfo.direccion || 'No especificada'}
                        </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="bg-blue-50 rounded-lg p-4">
                          <div className="text-2xl font-bold text-blue-600">
                            {companyInfo.total_usuarios}
                          </div>
                          <div className="text-sm text-blue-800">
                            Usuarios Activos
                          </div>
                        </div>
                        <div className="bg-green-50 rounded-lg p-4">
                          <div className="text-2xl font-bold text-green-600">
                            {companyInfo.total_dominios}
                          </div>
                          <div className="text-sm text-green-800">
                            Dominios Configurados
                          </div>
                        </div>
                      </div>

                      {userPermissions.is_company_admin && (
                        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
                          <div className="flex items-center">
                            <ExclamationTriangleIcon className="h-5 w-5 text-yellow-400 mr-2" />
                            <div className="text-sm text-yellow-800">
                              <strong>Administrador de Empresa:</strong> Tienes permisos para gestionar usuarios y configuraciones de la empresa.
                            </div>
                          </div>
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="text-center py-8">
                      <BuildingOfficeIcon className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                      <h3 className="text-lg font-medium text-gray-900 mb-2">
                        Sin Empresa Asociada
                      </h3>
                      <p className="text-gray-600">
                        Tu cuenta no está asociada a ninguna empresa.
                      </p>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserSettings;
